export class Periods {
  protected readonly periods = inject(PeriodsService);
  private readonly claims = inject(ClaimsService);
  private readonly people = inject(PeopleService);
  private readonly rates = inject(RatesService);
  private readonly sheets = inject(SheetService);
  protected readonly money = money;
  protected readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
    from: new FormControl('', { nonNullable: true }),
    to: new FormControl('', { nonNullable: true }),
  });
  protected readonly error = signal('');
  /** A submit is waiting for its answer; another submit meanwhile is ignored. */
  private saving = false;
  /** Each period's due-total in cents, by period id: the dues of the counting claims dated in it. */
  protected readonly dueTotals = computed(() => {
    const grades = new Map(this.people.people().map((p) => [p.id, p.grade]));
    const out = new Map<number, number>();
    for (const c of this.claims.claims().filter(counts)) {
      const period = this.periods.periodOn(c.date);
      const grade = grades.get(c.personId);
      if (!period || !grade) continue;
      const d = claimDue(c, (date) => this.rates.rateOn(grade, date));
      out.set(period.id, (out.get(period.id) ?? 0) + (d ?? 0));
    }
    return out;
  });

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
    effect(() => {
      this.sheets.loads();
      untracked(() => {
        this.reset();
      });
    });
  }

  private reset(): void {
    this.error.set('');
    this.form.reset({ name: '', from: '', to: '' }, { emitEvent: false });
  }

  protected submit(): void {
    if (this.saving) return;
    this.error.set('');
    const { name, from, to } = this.form.getRawValue();
    const n = name.trim();
    if (!n || !from || !to) {
      this.error.set('Enter a name, a from date and a to date.');
      return;
    }
    if (to < from) {
      this.error.set('A period cannot end before it starts.');
      return;
    }
    this.saving = true;
    this.periods.add({ name: n, from, to }).pipe(finalize(() => (this.saving = false))).subscribe({
      next: () => this.reset(),
      error: () => this.error.set('Could not add that period: its name is in use or it overlaps another.'),
    });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, of, tap } from 'rxjs';
import { SessionService } from './session.service';
import { SheetService } from './sheet.service';

export interface Period {
  id: number;
  /** Unique on the sheet. */
  name: string;
  /** The first date (yyyy-MM-dd) in the period. */
  from: string;
  /** The last date (yyyy-MM-dd) in the period. */
  to: string;
}

export interface PeriodForm {
  name: string;
  from: string;
  to: string;
}

// The active sheet's periods, by from-date. No two overlap, so a date (and the claim dated on it)
// belongs to at most one.
@Injectable({ providedIn: 'root' })
export class PeriodsService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(SessionService);
  private readonly sheets = inject(SheetService);
  private readonly list = signal<Period[]>([]);

  readonly periods = this.list.asReadonly();

  /** The period whose dates contain the date (yyyy-MM-dd); undefined when none does. */
  periodOn(date: string): Period | undefined {
    return this.list().find((p) => p.from <= date && date <= p.to);
  }

  /** Re-read the active sheet's periods from the store. */
  reload(): Observable<unknown> {
    const id = this.sheets.sheetId();
    if (!id) {
      this.list.set([]);
      return of(null);
    }
    return this.http
      .get<Period[]>(this.url(id), { headers: this.session.headers() })
      .pipe(tap((periods) => {
        if (this.sheets.sheetId() === id) this.list.set(periods);
      }));
  }

  /** Add a period; refused when it ends before it starts, reuses a name or overlaps another. */
  add(form: PeriodForm): Observable<Period> {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return this.http
      .post<Period>(this.url(id), form, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => [...all, p].sort((a, b) => a.from.localeCompare(b.from)))));
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/periods`;
  }
}

